<template>
  <component :is="embedded ? 'div' : 'el-dialog'" title="仓库交互日志" :visible.sync="visible" width="min(1180px, 96vw)" append-to-body :close-on-click-modal="false">
    <el-form v-if="!embedded" inline size="small" @submit.native.prevent="search"><el-form-item label="OMS 单号"><el-input v-model.trim="sn" clearable placeholder="输入完整执行单号" @keyup.enter.native="search" /></el-form-item><el-form-item label="动作"><el-select v-model="action" clearable placeholder="全部动作" style="width:160px"><el-option v-for="(label, code) in actions" :key="code" :label="label" :value="code" /></el-select></el-form-item><el-form-item label="结果"><el-select v-model="result" clearable placeholder="全部结果" style="width:135px"><el-option v-for="(label, code) in results" :key="code" :label="label" :value="code" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="load">刷新</el-button></el-form-item></el-form>
    <div class="log-summary" v-if="summary"><div class="log-counts"><strong>{{ sn ? '该单据全部日志' : '全部交互日志' }}</strong><span>共 {{ summary.total || 0 }} 条</span><span v-for="item in summary.counts || []" :key="item.action">{{ actions[item.action] || item.action }} {{ item.log_count }} 条</span></div><div class="create-summary" v-for="item in createRecords" :key="item.record.id"><strong>{{ item.label }}</strong><span>{{ item.record.create_time }}</span><el-tag size="mini" :type="item.record.result === 'SUCCESS' ? 'success' : item.record.result === 'FAILED' ? 'danger' : 'warning'">{{ results[item.record.result] || item.record.result }}</el-tag><span class="create-reason">{{ item.record.error_info || '—' }}</span><el-button v-hasPermi="['warehouse:wms:payload']" type="text" size="mini" @click="show(item.record)">查看{{ item.label }}报文</el-button></div><p v-if="!sn" class="hint">输入完整执行单号可查看首次及最近下发摘要。</p></div>
    <el-alert v-if="loadError" :title="loadError" type="error" :closable="false" show-icon />
    <el-table v-loading="loading" :data="rows" max-height="400"><el-table-column label="时间" prop="create_time" min-width="155" /><el-table-column label="平台 / 配置" min-width="160"><template slot-scope="s">{{ s.row.provider === 'QIMEN' ? '奇门' : '京东虎符' }} / {{ s.row.connection_name }}</template></el-table-column><el-table-column label="单号" prop="ticket_sn" min-width="225" show-overflow-tooltip /><el-table-column label="动作" width="90"><template slot-scope="s">{{ actions[s.row.action] }}</template></el-table-column><el-table-column label="方向" width="80"><template slot-scope="s">{{ s.row.direction === 'IN' ? '仓库回传' : '请求仓库' }}</template></el-table-column><el-table-column label="结果" width="100"><template slot-scope="s">{{ results[s.row.result] }}</template></el-table-column><el-table-column label="耗时(ms)" prop="duration_ms" width="90" /><el-table-column label="原因" prop="error_info" min-width="220" show-overflow-tooltip /><el-table-column label="操作" width="90" fixed="right"><template slot-scope="s"><el-button v-hasPermi="['warehouse:wms:payload']" type="text" @click="show(s.row)">查看报文</el-button></template></el-table-column></el-table>
    <div class="log-pages"><el-button size="small" :disabled="page === 1 || loading" @click="page--; load()">上一页</el-button><span>第 {{ page }} 页</span><el-button size="small" :disabled="rows.length < 50 || loading" @click="page++; load()">下一页</el-button></div>
    <div v-if="!embedded" slot="footer"><el-button @click="visible = false">关闭</el-button></div>
    <el-dialog title="交互报文（已脱敏）" :visible.sync="payloadVisible" width="850px" append-to-body><template v-if="payload"><p>请求编号：{{ payload.request_id }}</p><p>请求报文</p><pre>{{ payload.request_body }}</pre><p>响应报文</p><pre>{{ payload.response_body || '尚无响应' }}</pre><p>{{ payload.error_info }}</p></template><div slot="footer"><el-button @click="payloadVisible = false">关闭</el-button></div></el-dialog>
  </component>
</template>
<script>
import { interactionLogs, interactionLog, interactionLogSummary } from '@/api/warehouse/integration'
export default { props: { embedded: Boolean, ticketSn: { type: String, default: '' } }, watch: { ticketSn: { immediate: true, handler(v) { if (this.embedded) { this.sn = v; this.page = 1; this.load() } } } }, data() { return { visible: false, loading: false, rows: [], page: 1, sn: '', action: '', result: '', summary: null, loadError: '', payloadVisible: false, payload: null, sequence: 0, actions: { OUTBOUND_REPAIR: '测试链路恢复', OUTBOUND_RECEIPT: '出库回传', OUTBOUND_CREATE: '下发发货单', OUTBOUND_QUERY: '查询发货单', CREATE: '下发入库', QUERY: '查询结果', CANCEL: '申请取消', RECEIPT: '收货回传' }, results: { STARTED: '交互中', SUCCESS: '成功', FAILED: '失败', UNKNOWN: '结果待确认' } } }, computed: { createRecords() { if (!this.summary || !this.summary.first_create) return []; const rows = [{ label: '首次下发', record: this.summary.first_create }]; if (this.summary.latest_create && this.summary.latest_create.id !== this.summary.first_create.id) rows.push({ label: '最近下发', record: this.summary.latest_create }); return rows } }, methods: { open(sn = '') { this.sn = sn; this.page = 1; this.action = ''; this.result = ''; this.summary = null; this.visible = true; this.load() }, search() { this.page = 1; this.load() }, async load() { const seq = ++this.sequence; this.loading = true; this.loadError = ''; try { const [logs, summary] = await Promise.all([interactionLogs({ sn: this.sn, page: this.page, action: this.action || '', result: this.result || '' }), interactionLogSummary({ sn: this.sn })]); if (seq === this.sequence) { this.rows = logs.data; this.summary = summary.data } } catch (_) { if (seq === this.sequence) { this.rows = []; this.summary = null; this.loadError = '日志加载失败，请刷新重试' } } finally { if (seq === this.sequence) this.loading = false } }, async show(row) { this.payload = (await interactionLog(row.id)).data; this.payloadVisible = true } } }
</script>
<style scoped>.log-summary{background:#f6f8fb;border:1px solid #e3e9f1;border-radius:8px;padding:12px 16px;margin-bottom:14px}.log-counts,.create-summary{display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center;font-size:13px;line-height:1.6}.log-counts{color:#63748c;margin-bottom:10px}.create-summary{padding:8px 0;border-top:1px solid #e4eaf2}.create-reason{flex:1;min-width:160px;overflow-wrap:anywhere;color:#7c6346}.hint{font-size:13px;color:#8290a3;margin:6px 0}.log-pages{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:270px;overflow:auto;padding:12px;background:#f5f7fa}</style>
